def eval_command(args: list[str]) -> int:
    opts = CompileOptions(format="json", pretty=False, inputs={}, in_file=None, target="paged", features=set(), diagnostic_format="human")
    env_feats = os.environ.get("TYPST_FEATURES")
    if env_feats:
        rc = add_features(env_feats, opts)
        if rc is not None: return rc
    pos: list[str] = []
    after_dash = False
    i = 0
    while i < len(args):
        arg = args[i]
        if after_dash:
            pos.append(arg); i += 1; continue
        if arg == "--":
            after_dash = True; i += 1; continue
        if arg == "--help":
            out(help_text("eval", True)); return 0
        if arg == "-h":
            out(help_text("eval", False)); return 0
        name, eq, val_eq = arg.partition("=") if arg.startswith("--") else (arg, "", "")
        def getval(display: str) -> tuple[str | None, int | None]:
            nonlocal i
            if eq: return val_eq, None
            if i + 1 >= len(args): return None, missing_value(display)
            val = args[i + 1]
            if val.startswith("-"):
                return None, unexpected_arg(val, "eval [OPTIONS] <EXPRESSION>")
            i += 1
            return val, None
        if name == "--in":
            val, rc = getval("--in <IN>");
            if rc is not None: return rc
            opts.in_file = val
        elif name == "--target":
            val, rc = getval("--target <TARGET>");
            if rc is not None: return rc
            if val not in {"paged", "html"}:
                return invalid_value(str(val), "--target <TARGET>", "paged, html")
            opts.target = val
        elif name == "--format":
            val, rc = getval("--format <FORMAT>");
            if rc is not None: return rc
            if val not in {"json", "yaml"}:
                return invalid_value(str(val), "--format <FORMAT>", "json, yaml")
            opts.format = val
        elif name == "--pretty":
            opts.pretty = True
        elif name == "--input":
            val, rc = getval("--input <key=value>")
            if rc is not None: return rc
            if "=" not in str(val):
                return invalid_value(str(val), "--input <key=value>", reason="input must be a key and a value separated by an equal sign")
            k, v = str(val).split("=", 1); opts.inputs[k] = v
        elif name in {"--root", "--font-path", "--package-path", "--package-cache-path", "--creation-timestamp", "-j", "--jobs"}:
            val, rc = getval(name)
            if rc is not None: return rc
        elif name in {"--ignore-system-fonts", "--ignore-embedded-fonts"}:
            pass
        elif name == "--features":
            val, rc = getval("--features <FEATURES>")
            if rc is not None: return rc
            rc2 = add_features(str(val), opts)
            if rc2 is not None: return rc2
        elif name == "--diagnostic-format":
            val, rc = getval("--diagnostic-format <DIAGNOSTIC_FORMAT>")
            if rc is not None: return rc
            if val not in {"human", "short"}:
                return invalid_value(str(val), "--diagnostic-format <DIAGNOSTIC_FORMAT>", "human, short")
            opts.diagnostic_format = val
        elif arg.startswith("-"):
            return unexpected_arg(arg, "eval [OPTIONS] <EXPRESSION>")
        else:
            pos.append(arg)
        i += 1
    if not pos:
        return required_args(["<EXPRESSION>"], "eval <EXPRESSION>")
    if len(pos) > 1:
        return unexpected_arg(pos[1], "eval [OPTIONS] <EXPRESSION>", allow_tip=False)
    expr = pos[0]
    doc = None
    if opts.in_file:
        if opts.in_file == "-":
            doc = sys.stdin.read()
        else:
            try:
                doc = Path(str(opts.in_file)).read_text()
            except Exception:
                doc = ""
    try:
        value = eval_expr(expr, opts.inputs, doc)
        write_serialized(value, opts.format, opts.pretty)
    except EvalError as e:
        err("error: " + str(e) + "\n")
    return 0


