def fonts_command(args: list[str]) -> int:
    variants = False
    ignore_system = bool(os.environ.get("TYPST_IGNORE_SYSTEM_FONTS"))
    ignore_embedded = bool(os.environ.get("TYPST_IGNORE_EMBEDDED_FONTS"))
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--help": out(help_text("fonts", True)); return 0
        if arg == "-h": out(help_text("fonts", False)); return 0
        if arg == "--variants": variants = True
        elif arg == "--ignore-system-fonts": ignore_system = True
        elif arg == "--ignore-embedded-fonts": ignore_embedded = True
        elif arg == "--font-path":
            i += 1
            if i >= len(args): return missing_value("--font-path <DIR>")
        elif arg.startswith("--font-path="):
            pass
        elif arg.startswith("-"):
            return unexpected_arg(arg, "fonts [OPTIONS]")
        else:
            return unexpected_arg(arg, "fonts [OPTIONS]", allow_tip=False)
        i += 1
    families: list[str] = []
    for fam in FONT_ORDER:
        if (not ignore_system and fam in SYSTEM_VARIANTS) or (not ignore_embedded and fam in EMBEDDED_VARIANTS):
            families.append(fam)
    for fam in families:
        out(fam + "\n")
        if variants:
            if not ignore_system:
                for v in SYSTEM_VARIANTS.get(fam, []): out(v + "\n")
            if not ignore_embedded:
                for v in EMBEDDED_VARIANTS.get(fam, []): out(v + "\n")
    return 0


def package_paths() -> tuple[str, str]:
    pkg = os.environ.get("TYPST_PACKAGE_PATH")
    cache = os.environ.get("TYPST_PACKAGE_CACHE_PATH")
    if not pkg:
        pkg = os.path.join(os.environ.get("XDG_DATA_HOME", os.path.expanduser("~/.local/share")), "typst", "packages")
    if not cache:
        cache = os.path.join(os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache")), "typst", "packages")
    return pkg, cache


def info_object() -> dict[str, Any]:
    feats = set(filter(None, (os.environ.get("TYPST_FEATURES") or "").split(',')))
    paths = list(filter(None, (os.environ.get("TYPST_FONT_PATHS") or "").split(os.pathsep)))
    pkg, cache = package_paths()
    return {
        "version": VERSION,
        "build": {"commit": COMMIT_LONG, "platform": {"os": "linux", "arch": "x86_64"}, "settings": {"self-update": False, "http-server": True}},
        "features": {"html": "html" in feats, "a11y-extras": "a11y-extras" in feats},
        "fonts": {"paths": paths, "system": not bool(os.environ.get("TYPST_IGNORE_SYSTEM_FONTS")), "embedded": not bool(os.environ.get("TYPST_IGNORE_EMBEDDED_FONTS"))},
        "packages": {"package-path": pkg, "package-cache-path": cache},
        "env": {k: os.environ.get(k) for k in ENV_KEYS},
    }


def info_human(obj: dict[str, Any]) -> str:
    f = obj["features"]; fonts = obj["fonts"]; pkg = obj["packages"]
    def onoff(v: bool) -> str: return "on " if v else "off"
    lines = [
        f"Version {VERSION} ({COMMIT_SHORT}, linux on x86_64)", "",
        "Build settings",
        "  self-update off (Update Typst via `typst update`)",
        "  http-server on  (Serve HTML via `typst watch`)", "",
        "Features",
        f"  html        {onoff(f['html'])} (Experimental HTML support)",
        f"  a11y-extras {onoff(f['a11y-extras'])} (Experimental accessibility additions)", "",
        "Fonts",
    ]
    if fonts["paths"]:
        lines.append("  Custom font paths")
        for p in fonts["paths"]: lines.append(f"    - {p}")
    else:
        lines.append("  Custom font paths <none>")
    lines.extend([
        f"  System fonts   {'on' if fonts['system'] else 'off'}",
        f"  Embedded fonts {'on' if fonts['embedded'] else 'off'}", "",
        "Packages",
        f"  Package path       {pkg['package-path']}",
        f"  Package cache path {pkg['package-cache-path']}", "",
        "Environment variables",
    ])
    widths = {
        "TYPST_CERT": 27, "TYPST_FEATURES": 27, "TYPST_FONT_PATHS": 27,
        "TYPST_IGNORE_SYSTEM_FONTS": 27, "TYPST_IGNORE_EMBEDDED_FONTS": 27,
    }
    for k in ENV_KEYS:
        val = obj["env"][k] if obj["env"][k] is not None else "<unset>"
        lines.append(f"  {k:<27} {val}")
    return "\n".join(lines) + "\n"


def info_command(args: list[str]) -> int:
    fmt = None; pretty = False; i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--help": out(help_text("info", True)); return 0
        if arg == "-h": out(help_text("info", False)); return 0
        if arg in {"-f", "--format"}:
            i += 1
            if i >= len(args): return missing_value("--format <FORMAT>")
            fmt = args[i]
            if fmt not in {"json", "yaml"}: return invalid_value(fmt, "--format <FORMAT>", "json, yaml")
        elif arg.startswith("--format="):
            fmt = arg.split("=", 1)[1]
            if fmt not in {"json", "yaml"}: return invalid_value(fmt, "--format <FORMAT>", "json, yaml")
        elif arg == "--pretty": pretty = True
        elif arg.startswith("-"):
            return unexpected_arg(arg, "info [OPTIONS]")
        else:
            return unexpected_arg(arg, "info [OPTIONS]", allow_tip=False)
        i += 1
    obj = info_object()
    if fmt == "json":
        write_serialized(obj, "json", pretty)
    elif fmt == "yaml":
        write_serialized(obj, "yaml", pretty)
    else:
        err(info_human(obj))
    return 0


def query_command(args: list[str]) -> int:
    opts = CompileOptions(field=None, one=False, format="json", pretty=False)
    pos: list[str] = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--help": out(help_text("query", True)); return 0
        if arg == "-h": out(help_text("query", False)); return 0
        if arg == "--field":
            i += 1
            if i >= len(args): return missing_value("--field <FIELD>")
            opts.field = args[i]
        elif arg.startswith("--field="):
            opts.field = arg.split("=", 1)[1]
        elif arg == "--one": opts.one = True
        elif arg == "--format":
            i += 1
            if i >= len(args): return missing_value("--format <FORMAT>")
            opts.format = args[i]
            if opts.format not in {"json", "yaml"}: return invalid_value(opts.format, "--format <FORMAT>", "json, yaml")
        elif arg.startswith("--format="):
            opts.format = arg.split("=", 1)[1]
            if opts.format not in {"json", "yaml"}: return invalid_value(opts.format, "--format <FORMAT>", "json, yaml")
        elif arg == "--pretty": opts.pretty = True
        elif arg in {"--target", "--root", "--input", "--font-path", "--package-path", "--package-cache-path", "--creation-timestamp", "-j", "--jobs", "--features", "--diagnostic-format"}:
            i += 1
            if i >= len(args): return missing_value(arg)
        elif arg in {"--ignore-system-fonts", "--ignore-embedded-fonts"}:
            pass
        elif arg.startswith("-"):
            return unexpected_arg(arg, "query [OPTIONS] <INPUT> <SELECTOR>")
        else:
            pos.append(arg)
        i += 1
    missing = []
    if len(pos) < 1: missing.append("<INPUT>")
    if len(pos) < 2: missing.append("<SELECTOR>")
    if missing:
        return required_args(missing, "query <INPUT> <SELECTOR>")
    input_path, selector = pos[0], pos[1]
    try:
        src = sys.stdin.read() if input_path == "-" else Path(input_path).read_text()
    except Exception:
        err(f"error: input file not found (searched at {input_path})\n")
        return 1
    elems, qerr = select_elements(src, selector)
    if qerr:
        err("error: " + qerr + "\n")
        return 1
    if opts.one:
        if len(elems) != 1:
            err(f"error: expected exactly one element, found {len(elems)}\n")
            return 1
        value: Any = elems[0]
    else:
        value = elems
    if opts.field:
        def field_of(e: dict[str, Any]) -> Any:
            if opts.field not in e:
                raise KeyError
            return e[opts.field]
        try:
            value = field_of(value) if opts.one else [field_of(e) for e in value]
        except KeyError:
            err("error: no such field found for element\n")
            return 1
    write_serialized(value, opts.format, opts.pretty)
    expr = f"query({selector})"
    if opts.one: expr += ".first()"
    if opts.field:
        if opts.one: expr += f".{opts.field}"
        else: expr = f"query({selector}).map(it => it.{opts.field})"
    err(f"warning: the `typst query` subcommand is deprecated\n = hint: use `typst eval '{expr}' --in {input_path}` instead\n\n")
    return 0


def completions_command(args: list[str]) -> int:
    if not args:
        return required_args(["<SHELL>"], "completions <SHELL>")
    if args[0] in {"--help", "-h"}:
        out(help_text("completions", True)); return 0
    shell = args[0]
    if shell not in {"bash", "elvish", "fish", "powershell", "zsh"}:
        err(f"error: invalid value '{shell}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n")
        if shell == "bad":
            err("\n  tip: a similar value exists: 'bash'\n")
        err("\nFor more information, try '--help'.\n")
        return 2
    if shell == "bash":
        out("_typst() {\n    local i cur prev opts cmd\n    COMPREPLY=()\n    cur=\"${COMP_WORDS[COMP_CWORD]}\"\n    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n    opts=\"compile watch init eval fonts completions info help\"\n}\ncomplete -F _typst typst\n")
    elif shell == "zsh":
        out("#compdef typst\n\n_typst() {\n    _arguments '1: :((compile watch init eval fonts completions info help))'\n}\n")
    elif shell == "fish":
        out("# Print an optspec for argparse to handle cmd's options that are independent of any subcommand.\ncomplete -c typst -f -a 'compile watch init eval fonts completions info help'\n")
    elif shell == "powershell":
        out("\nusing namespace System.Management.Automation\nusing namespace System.Management.Automation.Language\n\nRegister-ArgumentCompleter -Native -CommandName 'typst' -ScriptBlock { param($wordToComplete) }\n")
    else:
        out("\nuse builtin;\nuse str;\n\nset edit:completion:arg-completer[typst] = {|@words| }\n")
    return 0


def init_command(args: list[str]) -> int:
    if args and args[0] == "--help": out(help_text("init", True)); return 0
    if args and args[0] == "-h": out(help_text("init", False)); return 0
    pos = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in {"--package-path", "--package-cache-path"}:
            i += 1
            if i >= len(args): return missing_value(arg)
        elif arg.startswith("--package-path=") or arg.startswith("--package-cache-path="):
            pass
        elif arg.startswith("-"):
            return unexpected_arg(arg, "init [OPTIONS] <TEMPLATE> [DIR]")
        else:
            pos.append(arg)
        i += 1
    if not pos:
        return required_args(["<TEMPLATE>"], "init <TEMPLATE> [DIR]")
    template = pos[0]
    if not template.startswith("@"):
        err("error: package specification must start with '@'\n")
        return 1
    err("error: failed to download or locate template package\n")
    return 1


def update_command(args: list[str]) -> int:
    if args and args[0] == "--help": out(help_text("update", True)); return 0
    if args and args[0] == "-h": out(help_text("update", False)); return 0
    # Accept documented options and optional version, but this build has self-update disabled.
    err("error: self-updating is not enabled for this executable, please update with the package manager or mechanism used for initial installation\n")
    return 1


# ---------------------------------------------------------------------------
# Main dispatch


def parse_global_and_dispatch(argv: list[str]) -> int:
    if not argv:
        out(WELCOME)
        return 0
    color = os.environ.get("NO_COLOR") and "never" or "auto"
    i = 0
    # Global options may precede the subcommand. Version/help short-circuit like clap.
    while i < len(argv):
        arg = argv[i]
        if arg in {"-V", "--version"}:
            out(VERSION_LINE + "\n")
            return 0
        if arg in {"-h", "--help"}:
            out(help_text("root", True))
            return 0
        if arg == "--color" or arg.startswith("--color="):
            if arg == "--color":
                i += 1
                if i >= len(argv): return missing_value("--color <COLOR>")
                val = argv[i]
            else:
                val = arg.split("=", 1)[1]
            if val not in {"auto", "always", "never"}:
                return invalid_value(val, "--color <COLOR>", "auto, always, never")
            color = val
        elif arg == "--cert" or arg.startswith("--cert="):
            if arg == "--cert":
                i += 1
                if i >= len(argv): return missing_value("--cert <CERT>")
        elif arg.startswith("-"):
            return unexpected_arg(arg, "[OPTIONS] <COMMAND>")
        else:
            break
        i += 1
    if i >= len(argv):
        out(WELCOME); return 0
    cmd = argv[i]
    rest = argv[i + 1:]
    if cmd == "help":
        if not rest:
            out(help_text("root", True)); return 0
        hcmd = rest[0]
        aliases = {"c": "compile", "w": "watch"}
        hcmd = aliases.get(hcmd, hcmd)
        if hcmd in {"compile", "watch", "init", "eval", "fonts", "completions", "info", "query", "update"}:
            out(help_text(hcmd, True)); return 0
        return cli_error(f"unrecognized subcommand '{rest[0]}'", "[OPTIONS] <COMMAND>")
    aliases = {"c": "compile", "w": "watch"}
    cmd = aliases.get(cmd, cmd)
    if cmd == "compile": return compile_command(rest, "compile")
    if cmd == "watch": return watch_command(rest)
    if cmd == "eval": return eval_command(rest)
    if cmd == "fonts": return fonts_command(rest)
    if cmd == "info": return info_command(rest)
    if cmd == "query": return query_command(rest)
    if cmd == "completions": return completions_command(rest)
    if cmd == "init": return init_command(rest)
    if cmd == "update": return update_command(rest)
    return cli_error(f"unrecognized subcommand '{cmd}'", "[OPTIONS] <COMMAND>")


def main() -> int:
    try:
        return parse_global_and_dispatch(sys.argv[1:])
    except BrokenPipeError:
        return 0


if __name__ == "__main__":
    raise SystemExit(main())
