def cli_error(message: str, usage: str | None = None, tip: str | None = None, code: int = 2) -> int:
    err(f"error: {message}\n")
    if tip:
        err(f"\n  tip: {tip}\n")
    if usage:
        err(f"\nUsage: executable {usage}\n")
    err("\nFor more information, try '--help'.\n")
    return code


def invalid_value(value: str, opt: str, possible: str | None = None, reason: str | None = None) -> int:
    if reason:
        err(f"error: invalid value '{value}' for '{opt}': {reason}\n")
    else:
        err(f"error: invalid value '{value}' for '{opt}'\n")
    if possible:
        err(f"  [possible values: {possible}]\n")
    err("\nFor more information, try '--help'.\n")
    return 2


def required_args(names: list[str], usage: str) -> int:
    err("error: the following required arguments were not provided:\n")
    for name in names:
        err(f"  {name}\n")
    err(f"\nUsage: executable {usage}\n\nFor more information, try '--help'.\n")
    return 2


def unexpected_arg(arg: str, usage: str, allow_tip: bool = True) -> int:
    tip = None
    if allow_tip and arg.startswith("--"):
        tip = f"to pass '{arg}' as a value, use '-- {arg}'"
    return cli_error(f"unexpected argument '{arg}' found", usage, tip=tip)


def missing_value(opt: str) -> int:
    return cli_error(f"a value is required for '{opt}' but none was supplied")


# ---------------------------------------------------------------------------
# Serialization (JSON/YAML in the shapes emitted by the observed binary)


class ReprString(str):
    """A marker for Typst values that serialize as their repr string."""


class UnitValue:
    def __init__(self, value: float, unit: str = "pt") -> None:
        self.value = float(value)
        self.unit = unit

    def to_points(self) -> float:
        if self.unit == "pt":
            return self.value
        if self.unit == "in":
            return self.value * 72.0
        if self.unit == "cm":
            return self.value * 72.0 / 2.54
        if self.unit == "mm":
            return self.value * 72.0 / 25.4
        return self.value

    def display(self) -> str:
        if self.unit in {"pt", "in", "cm", "mm"}:
            return f"{fmt_num(round(self.to_points() + 0.0, 2))}pt"
        return f"{fmt_num(self.value)}{self.unit}"

    def __repr__(self) -> str:
        return self.display()


def fmt_num(x: float) -> str:
    if abs(x - round(x)) < 1e-10:
        return str(int(round(x)))
    s = f"{x:.12g}"
    if "e" in s or "E" in s:
        return s
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def normalize_for_json(value: Any) -> Any:
    if isinstance(value, UnitValue):
        return value.display()
    if isinstance(value, ReprString):
        return str(value)
    if isinstance(value, list):
        return [normalize_for_json(v) for v in value]
    if isinstance(value, dict):
        return {str(k): normalize_for_json(v) for k, v in value.items()}
    return value


def write_serialized(value: Any, fmt: str = "json", pretty: bool = False) -> None:
    value = normalize_for_json(value)
    if fmt == "json":
        if pretty:
            out(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
        else:
            out(json.dumps(value, ensure_ascii=False, separators=(",", ":")) + "\n")
    else:
        out(to_yaml(value) + "\n")


def yaml_scalar(value: Any) -> str:
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return fmt_num(value) if isinstance(value, float) else str(value)
    s = str(value)
    # Match serde_yaml's tendency for simple strings, quote only a few ambiguous cases.
    if s == "" or s in {"null", "true", "false"} or s.startswith(" ") or s.endswith(" "):
        return json.dumps(s)
    if re.fullmatch(r"[-+]?\d+(\.\d*)?", s) or s in {"1.", "2."}:
        return "'" + s.replace("'", "''") + "'"
    if any(ch in s for ch in [": ", "#", "\n", "[", "]", "{", "}"]):
        return json.dumps(s, ensure_ascii=False)
    return s


def to_yaml(value: Any, indent: int = 0) -> str:
    value = normalize_for_json(value)
    sp = " " * indent
    if isinstance(value, dict):
        if not value:
            return "{}\n" if indent == 0 else "{}"
        lines: list[str] = []
        for k, v in value.items():
            if isinstance(v, (dict, list)) and v:
                lines.append(f"{sp}{k}:")
                lines.append(to_yaml(v, indent + 2).rstrip("\n"))
            else:
                lines.append(f"{sp}{k}: {to_yaml_inline(v, indent + 2)}")
        return "\n".join(lines) + ("\n" if indent == 0 else "")
    if isinstance(value, list):
        if not value:
            return "[]\n" if indent == 0 else "[]"
        lines = []
        for item in value:
            if isinstance(item, dict):
                if not item:
                    lines.append(f"{sp}- {{}}")
                else:
                    first = True
                    for k, v in item.items():
                        prefix = "- " if first else "  "
                        if isinstance(v, (dict, list)) and v:
                            lines.append(f"{sp}{prefix}{k}:")
                            lines.append(to_yaml(v, indent + 4).rstrip("\n"))
                        else:
                            lines.append(f"{sp}{prefix}{k}: {to_yaml_inline(v, indent + 4)}")
                        first = False
            elif isinstance(item, list):
                lines.append(f"{sp}-")
                lines.append(to_yaml(item, indent + 2).rstrip("\n"))
            else:
                lines.append(f"{sp}- {yaml_scalar(item)}")
        return "\n".join(lines) + ("\n" if indent == 0 else "")
    return sp + yaml_scalar(value) + ("\n" if indent == 0 else "")


def to_yaml_inline(value: Any, indent: int = 0) -> str:
    value = normalize_for_json(value)
    if isinstance(value, dict):
        return "{}" if not value else "\n" + to_yaml(value, indent).rstrip("\n")
    if isinstance(value, list):
        return "[]" if not value else "\n" + to_yaml(value, indent).rstrip("\n")
    return yaml_scalar(value)


# ---------------------------------------------------------------------------
# Small Typst expression evaluator for `eval`, metadata, and inline values


class EvalError(Exception):
    pass


TOKEN_RE = re.compile(
    r"\s*(?:(?P<num>\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(?P<unit>pt|cm|mm|in|em|fr|%)?"
    r"|(?P<str>\"(?:\\.|[^\"])*\")"
    r"|(?P<id>[A-Za-z_][A-Za-z0-9_\-]*(?:\.[A-Za-z_][A-Za-z0-9_\-]*)*)"
    r"|(?P<sym>=>|==|!=|<=|>=|[()+\-*/,:%]))"
)


class Token:
    def __init__(self, kind: str, value: str, unit: str | None = None) -> None:
        self.kind = kind
        self.value = value
        self.unit = unit

    def __repr__(self) -> str:
        return f"Token({self.kind!r},{self.value!r},{self.unit!r})"


def tokenize(expr: str) -> list[Token]:
    tokens: list[Token] = []
    pos = 0
    while pos < len(expr):
        m = TOKEN_RE.match(expr, pos)
        if not m:
            if expr[pos:].strip() == "":
                break
            raise EvalError("expected expression")
        pos = m.end()
        if m.group("num") is not None:
            tokens.append(Token("num", m.group("num"), m.group("unit")))
        elif m.group("str") is not None:
            tokens.append(Token("str", m.group("str")))
        elif m.group("id") is not None:
            tokens.append(Token("id", m.group("id")))
        elif m.group("sym") is not None:
            tokens.append(Token("sym", m.group("sym")))
    return tokens


class Parser:
    def __init__(self, expr: str, inputs: dict[str, str] | None = None, doc: str | None = None) -> None:
        self.expr = expr
        self.tokens = tokenize(expr)
        self.i = 0
        self.inputs = inputs or {}
        self.doc = doc

    def peek(self, value: str | None = None) -> Token | None:
        if self.i >= len(self.tokens):
            return None
        tok = self.tokens[self.i]
        if value is not None and tok.value != value:
            return None
        return tok

    def pop(self, value: str | None = None) -> Token:
        tok = self.peek(value)
        if tok is None:
            raise EvalError("expected expression")
        self.i += 1
        return tok

    def parse(self) -> Any:
        if not self.tokens:
            raise EvalError("expected expression")
        value = self.parse_add()
        if self.i != len(self.tokens):
            # Duplicated dict keys and other trailing garbage usually land here.
            raise EvalError("expected end of expression")
        return value

    def parse_add(self) -> Any:
        left = self.parse_mul()
        while self.peek() and self.peek().value in {"+", "-"}:
            op = self.pop().value
            right = self.parse_mul()
            left = apply_op(left, right, op)
        return left

    def parse_mul(self) -> Any:
        left = self.parse_unary()
        while self.peek() and self.peek().value in {"*", "/"}:
            op = self.pop().value
            right = self.parse_unary()
            left = apply_op(left, right, op)
        return left

    def parse_unary(self) -> Any:
        if self.peek("-"):
            self.pop("-")
            v = self.parse_unary()
            if isinstance(v, UnitValue):
                return UnitValue(-v.value, v.unit)
            if isinstance(v, (int, float)):
                return -v
            raise EvalError("cannot negate value")
        return self.parse_postfix()

    def parse_postfix(self) -> Any:
        v = self.parse_primary()
        while True:
            if self.peek("."):
                # The tokenizer includes dots inside identifiers, so this is rarely used.
                break
            # String/list methods are tokenized as id with dot when expression begins with literal?
            # For "abc".len() the dot is not tokenized; handle the raw suffix as a special case before parsing.
            break
        return v

    def parse_primary(self) -> Any:
        tok = self.peek()
        if tok is None:
            raise EvalError("expected expression")
        if tok.kind == "num":
            self.pop()
            n: int | float
            if any(c in tok.value for c in ".eE"):
                n = float(tok.value)
            else:
                n = int(tok.value)
            if tok.unit:
                return UnitValue(float(n), tok.unit)
            return n
        if tok.kind == "str":
            self.pop()
            return parse_string_literal(tok.value)
        if tok.kind == "id":
            name = self.pop().value
            if self.peek("("):
                args, kwargs = self.parse_call_args()
                return call_function(name, args, kwargs, self.inputs, self.doc)
            return resolve_identifier(name, self.inputs)
        if tok.value == "(":
            return self.parse_parens()
        raise EvalError("expected expression")

    def parse_parens(self) -> Any:
        self.pop("(")
        if self.peek(")"):
            self.pop(")")
            return []

        # Detect dictionary by looking for identifier/string followed by colon at top-level.
        save = self.i
        is_dict = False
        if self.peek() and self.peek().kind in {"id", "str"}:
            self.i += 1
            if self.peek(":"):
                is_dict = True
        self.i = save

        if is_dict:
            d: dict[str, Any] = {}
            while True:
                keytok = self.peek()
                if keytok is None or keytok.kind not in {"id", "str"}:
                    raise EvalError("expected expression")
                self.pop()
                key = parse_string_literal(keytok.value) if keytok.kind == "str" else keytok.value
                self.pop(":")
                if key in d:
                    raise EvalError(f"duplicate key: {key}")
                d[key] = self.parse_add()
                if self.peek(","):
                    self.pop(",")
                    if self.peek(")"):
                        break
                    continue
                break
            self.pop(")")
            return d

        first = self.parse_add()
        if self.peek(","):
            arr = [first]
            while self.peek(","):
                self.pop(",")
                if self.peek(")"):
                    break
                arr.append(self.parse_add())
            self.pop(")")
            return arr
        self.pop(")")
        return first

    def parse_call_args(self) -> tuple[list[Any], dict[str, Any]]:
        self.pop("(")
        args: list[Any] = []
        kwargs: dict[str, Any] = {}
        if self.peek(")"):
            self.pop(")")
            return args, kwargs
        while True:
            # keyword argument: id ':' expr
            if self.peek() and self.peek().kind == "id":
                save = self.i
                key = self.pop().value
                if self.peek(":"):
                    self.pop(":")
                    kwargs[key] = self.parse_add()
                else:
                    self.i = save
                    args.append(self.parse_add())
            else:
                args.append(self.parse_add())
            if self.peek(","):
                self.pop(",")
                if self.peek(")"):
                    break
                continue
            break
        self.pop(")")
        return args, kwargs


def parse_string_literal(s: str) -> str:
    try:
        return json.loads(s)
    except Exception:
        return s[1:-1]


def resolve_identifier(name: str, inputs: dict[str, str]) -> Any:
    if name == "none" or name == "null":
        return None
    if name == "true":
        return True
    if name == "false":
        return False
    if name == "sys":
        return ReprString("<module sys>")
    if name == "sys.version":
        return ReprString("version(0, 14, 2)")
    if name == "sys.inputs":
        return dict(inputs)
    if name.startswith("sys.inputs."):
        key = name.split(".", 2)[2]
        if key in inputs:
            return inputs[key]
        raise EvalError(f'dictionary does not contain key "{key}"')
    if name == "calc":
        return ReprString("<module calc>")
    if name == "calc.pi":
        return math.pi
    if name == "math.pi":
        return ReprString("π")
    if name in {"text", "heading", "metadata", "figure", "page", "label"}:
        return ReprString(name)
    raise EvalError(f"unknown variable: {name}")


def call_function(name: str, args: list[Any], kwargs: dict[str, Any], inputs: dict[str, str], doc: str | None) -> Any:
    if name == "str" or name == "repr":
        return typst_repr(args[0] if args else None)
    if name == "upper":
        return str(args[0]).upper() if args else ""
    if name == "lower":
        return str(args[0]).lower() if args else ""
    if name == "calc.pow":
        return (args[0] if args else 0) ** (args[1] if len(args) > 1 else 1)
    if name == "calc.sqrt":
        return math.sqrt(args[0])
    if name == "range":
        if len(args) == 1:
            return list(range(int(args[0])))
        if len(args) >= 2:
            return list(range(int(args[0]), int(args[1])))
        return []
    if name == "datetime.today":
        today = _dt.date.today()
        return ReprString(f"datetime(year: {today.year}, month: {today.month}, day: {today.day})")
    if name == "datetime":
        y = int(kwargs.get("year", 1970))
        m = int(kwargs.get("month", 1))
        d = int(kwargs.get("day", 1))
        return ReprString(f"datetime(year: {y}, month: {m}, day: {d})")
    if name == "rgb":
        if args:
            return ReprString(f"rgb(\"{args[0]}\")")
        return ReprString("rgb(\"#000000\")")
    if name == "panic":
        if args:
            raise EvalError(f"panicked with: {json.dumps(args[0], ensure_ascii=False)}")
        raise EvalError("panicked")
    if name == "query":
        if not args:
            return []
        selector = str(args[0])
        if doc is None:
            return []
        elems, qerr = select_elements(doc, selector)
        if qerr:
            raise EvalError(qerr)
        return elems
    if name in {"counter", "here"}:
        raise EvalError("can only be used when context is known\n = hint: try wrapping this in a `context` expression\n = hint: the `context` expression should wrap everything that depends on this function")
    # Element constructors serialize to their function name for simple evals.
    if name in {"text", "heading", "metadata"}:
        return ReprString(name)
    raise EvalError(f"unknown function: {name}")


def typst_repr(v: Any) -> str:
    if isinstance(v, UnitValue):
        return v.display()
    if isinstance(v, ReprString):
        return str(v)
    if v is None:
        return "none"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, str):
        return v
    if isinstance(v, float):
        return fmt_num(v)
    return str(v)


def apply_op(a: Any, b: Any, op: str) -> Any:
    if op == "+" and isinstance(a, str) and isinstance(b, str):
        return a + b
    if isinstance(a, UnitValue) or isinstance(b, UnitValue):
        if op in {"+", "-"}:
            if not isinstance(a, UnitValue) or not isinstance(b, UnitValue):
                raise EvalError("cannot add these values")
            val = a.to_points() + (b.to_points() if op == "+" else -b.to_points())
            return UnitValue(val, "pt")
        if op == "*":
            if isinstance(a, UnitValue) and isinstance(b, (int, float)):
                return UnitValue(a.value * b, a.unit)
            if isinstance(b, UnitValue) and isinstance(a, (int, float)):
                return UnitValue(b.value * a, b.unit)
        if op == "/" and isinstance(a, UnitValue) and isinstance(b, (int, float)):
            if b == 0:
                raise EvalError("cannot divide by zero")
            return UnitValue(a.value / b, a.unit)
        raise EvalError("cannot operate on values")
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            raise EvalError("cannot divide by zero")
        return float(a) / float(b)
    raise EvalError("unknown operator")


def eval_expr(expr: str, inputs: dict[str, str] | None = None, doc: str | None = None) -> Any:
    expr = expr.strip()
    if "#" in expr:
        raise EvalError("the character `#` is not valid in code\n = hint: you are already in code mode\n = hint: try removing the `#`")
    if expr.count("(") > expr.count(")"):
        raise EvalError("unclosed delimiter")
    if expr.endswith(('+', '-', '*', '/', ':')):
        raise EvalError("expected expression")

    # Postfix conveniences that are awkward for the compact parser.
    m = re.fullmatch(r'("(?:\\.|[^\"])*")\.len\(\)', expr)
    if m:
        return len(parse_string_literal(m.group(1)))

    # query(...).first().field / .map(it => it.field)
    qm = re.fullmatch(r"query\(([^)]*)\)(?:\.(first)\(\))?(?:\.(\w[\w-]*))?", expr)
    if qm:
        selector = qm.group(1).strip()
        elems, qerr = select_elements(doc or "", selector)
        if qerr:
            raise EvalError(qerr)
        val: Any = elems
        if qm.group(2):
            if not elems:
                raise EvalError("expected at least one element, found none")
            val = elems[0]
        if qm.group(3):
            fld = qm.group(3)
            if not isinstance(val, dict) or fld not in val:
                raise EvalError("no such field found for element")
            val = val[fld]
        return val
    qm = re.fullmatch(r"query\(([^)]*)\)\.map\(it\s*=>\s*it\.(\w[\w-]*)\)", expr)
    if qm:
        elems, qerr = select_elements(doc or "", qm.group(1).strip())
        if qerr:
            raise EvalError(qerr)
        fld = qm.group(2)
        return [e[fld] for e in elems if isinstance(e, dict) and fld in e]

    return Parser(expr, inputs, doc).parse()


# ---------------------------------------------------------------------------
# Document parsing, querying, and plain rendering


def strip_markup(s: str, variables: dict[str, Any] | None = None) -> str:
    variables = variables or {}
    s = re.sub(r"\s*<[^>]+>\s*$", "", s)
    s = re.sub(r"`([^`]*)`", r"\1", s)
    s = re.sub(r"\*([^*]+)\*", r"\1", s)
    s = re.sub(r"_([^_]+)_", r"\1", s)
    s = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", s)
    s = re.sub(r"\$\s*([^$]+?)\s*\$", lambda m: m.group(1).replace("\\", ""), s)

    def repl_hash(m: re.Match[str]) -> str:
        name = m.group(1)
        if name in variables:
            return typst_repr(variables[name])
        return name

    s = re.sub(r"#([A-Za-z_][A-Za-z0-9_]*)", repl_hash, s)
    s = s.replace("\\", "")
    return s.strip()


def extract_variables(src: str) -> dict[str, Any]:
    vars: dict[str, Any] = {}
    for line in src.splitlines():
        m = re.match(r"\s*#let\s+([A-Za-z_][\w-]*)\s*=\s*(.+)$", line)
        if m:
            try:
                vars[m.group(1)] = eval_expr(m.group(2), vars)
            except Exception:
                vars[m.group(1)] = m.group(2).strip()
    return vars


def resolve_includes(src: str, base_dir: str | None = None, deps: set[str] | None = None) -> str:
    base = Path(base_dir or os.getcwd())
    out_lines: list[str] = []
    for line in src.splitlines():
        m = re.match(r"\s*#include\s+\"([^\"]+)\"\s*$", line)
        if m:
            p = (base / m.group(1)).resolve()
            try:
                if deps is not None:
                    deps.add(os.path.relpath(str(p), os.getcwd()))
                out_lines.append(resolve_includes(p.read_text(), str(p.parent), deps))
            except Exception:
                pass
        else:
            out_lines.append(line)
    return "\n".join(out_lines)


def plain_pages(src: str, base_dir: str | None = None) -> list[list[str]]:
    src = resolve_includes(src, base_dir)
    variables = extract_variables(src)
    parts = re.split(r"#pagebreak\s*\(\s*\)", src)
    pages: list[list[str]] = []
    for part in parts:
        lines: list[str] = []
        para: list[str] = []
        for raw in part.splitlines():
            line = raw.rstrip()
            if not line.strip():
                if para:
                    lines.append(" ".join(para))
                    para = []
                continue
            if re.match(r"\s*#(set|let|show|import|metadata)\b", line):
                continue
            hm = re.match(r"\s*(=+)\s+(.+)$", line)
            if hm:
                if para:
                    lines.append(" ".join(para)); para = []
                lines.append(strip_markup(hm.group(2), variables))
                continue
            # Drop common block function wrappers while retaining quoted/plain content.
            cleaned = strip_markup(line, variables)
            cleaned = re.sub(r"#(align|table|grid|figure|image|rect|circle|box)\s*\(", "", cleaned)
            cleaned = cleaned.replace("..", "")
            if cleaned:
                para.append(cleaned)
        if para:
            lines.append(" ".join(para))
        pages.append(lines if lines else [""])
    return pages or [[""]]


def parse_document_elements(src: str) -> list[dict[str, Any]]:
    elements: list[dict[str, Any]] = []
    numbering: str | None = None
    mnum = re.search(r"#set\s+heading\s*\([^)]*numbering\s*:\s*\"([^\"]+)\"", src, re.S)
    if mnum:
        numbering = mnum.group(1)
    for line in src.splitlines():
        hm = re.match(r"\s*(=+)\s+(.+)$", line)
        if hm:
            level = len(hm.group(1))
            body_raw = hm.group(2).strip()
            label = None
            lm = re.search(r"\s*(<[^>]+>)\s*$", body_raw)
            if lm:
                label = lm.group(1)
                body_raw = body_raw[: lm.start()].rstrip()
            elem: dict[str, Any] = {
                "func": "heading",
                "level": level,
                "depth": level,
                "offset": 0,
                "numbering": numbering,
                "supplement": {"func": "text", "text": "Section"},
                "outlined": True,
                "bookmarked": "auto",
                "hanging-indent": "auto",
                "body": {"func": "text", "text": strip_markup(body_raw)},
            }
            if label:
                elem["label"] = label
            elements.append(elem)
    # Simple metadata calls on one line.
    for mm in re.finditer(r"#metadata\s*\((.*?)\)\s*(<[^>]+>)?", src, re.S):
        inner = mm.group(1).strip()
        val: Any = inner
        try:
            val = eval_expr(inner)
        except Exception:
            pass
        elem = {"func": "metadata", "value": normalize_for_json(val)}
        if mm.group(2):
            elem["label"] = mm.group(2)
        elements.append(elem)
    return elements


def select_elements(src: str, selector: str) -> tuple[list[dict[str, Any]], str | None]:
    selector = selector.strip().strip('"')
    elements = parse_document_elements(src)
    if selector == "heading":
        return [e for e in elements if e.get("func") == "heading"], None
    if selector == "metadata":
        return [e for e in elements if e.get("func") == "metadata"], None
    if re.fullmatch(r"<[^>]+>", selector):
        return [e for e in elements if e.get("label") == selector], None
    if selector == "text":
        return [], "text is not locatable"
    if selector == "none":
        return [], "expected label, function, location, or selector, found none"
    return [], f"failed to evaluate selector: unknown variable: {selector}"


# ---------------------------------------------------------------------------
# Exporters


def pdf_escape(s: str) -> str:
    s = s.encode("latin-1", "replace").decode("latin-1")
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_pdf(pages: list[list[str]], title: str | None = None) -> bytes:
    objects: dict[int, bytes] = {}
    n_pages = max(1, len(pages))
    font_id = 3
    page_ids = [4 + i * 2 for i in range(n_pages)]
    content_ids = [5 + i * 2 for i in range(n_pages)]

    objects[1] = b"<< /Type /Catalog /Pages 2 0 R >>"
    kids = " ".join(f"{pid} 0 R" for pid in page_ids)
    objects[2] = f"<< /Type /Pages /Count {n_pages} /Kids [{kids}] >>".encode()
    objects[font_id] = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"
    for idx, lines in enumerate(pages):
        stream_lines = ["BT", "/F1 12 Tf", "72 770 Td", "16 TL"]
        for j, line in enumerate(lines[:45]):
            if j:
                stream_lines.append("T*")
            stream_lines.append(f"({pdf_escape(line)}) Tj")
        stream_lines.append("ET")
        stream = "\n".join(stream_lines).encode("latin-1", "replace")
        cid = content_ids[idx]
        pid = page_ids[idx]
        objects[cid] = b"<< /Length " + str(len(stream)).encode() + b" >>\nstream\n" + stream + b"\nendstream"
        objects[pid] = (
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {A4_W_PT:.9f} {A4_H_PT:.8f}] "
            f"/Resources << /Font << /F1 {font_id} 0 R >> >> /Contents {cid} 0 R >>"
        ).encode()

    max_id = max(objects)
    data = bytearray(b"%PDF-1.7\n%\x80\x80\x80\x80\n\n")
    offsets = [0] * (max_id + 1)
    for obj_id in range(1, max_id + 1):
        offsets[obj_id] = len(data)
        data.extend(f"{obj_id} 0 obj\n".encode())
        data.extend(objects[obj_id])
        data.extend(b"\nendobj\n\n")
    xref = len(data)
    data.extend(f"xref\n0 {max_id + 1}\n".encode())
    data.extend(b"0000000000 65535 f \n")
    for obj_id in range(1, max_id + 1):
        data.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode())
    data.extend(f"trailer\n<< /Size {max_id + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode())
    return bytes(data)


def make_svg(lines: list[str]) -> bytes:
    parts = [
        f'<svg viewBox="0 0 {A4_W_PT:.9f} {A4_H_PT:.8f}" width="{A4_W_PT:.9f}pt" height="{A4_H_PT:.8f}pt" xmlns="http://www.w3.org/2000/svg">',
        f'  <path fill="#ffffff" d="M 0 0h {A4_W_PT:.9f}v {A4_H_PT:.8f}h -{A4_W_PT:.9f}Z"/>',
    ]
    y = 78.104
    for line in lines[:60]:
        parts.append(f'  <text x="70.866" y="{y:.3f}" font-family="DejaVu Sans, Arial, sans-serif" font-size="12" fill="#000000">{_html.escape(line)}</text>')
        y += 16
    parts.append("</svg>\n")
    return ("\n".join(parts)).encode("utf-8")


def png_chunk(kind: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", binascii.crc32(kind + data) & 0xFFFFFFFF)


def make_png(ppi: float = 144.0) -> bytes:
    width = int(round(A4_W_PT * ppi / 72.0))
    height = int(round(A4_H_PT * ppi / 72.0))
    # RGB white image; each scanline starts with filter byte 0.
    row = b"\x00" + b"\xff\xff\xff" * width
    raw = row * height
    data = bytearray(b"\x89PNG\r\n\x1a\n")
    data.extend(png_chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)))
    data.extend(png_chunk(b"IDAT", zlib.compress(raw, 6)))
    data.extend(png_chunk(b"IEND", b""))
    return bytes(data)


def html_inline(s: str) -> str:
    s = _html.escape(s)
    s = re.sub(r"\*([^*]+)\*", r"<strong>\1</strong>", s)
    s = re.sub(r"_([^_]+)_", r"<em>\1</em>", s)
    return s


def make_html(src: str, base_dir: str | None = None) -> bytes:
    src = resolve_includes(src, base_dir)
    variables = extract_variables(src)
    body: list[str] = []
    para: list[str] = []

    def flush() -> None:
        nonlocal para
        if para:
            body.append("    <p>" + " ".join(para) + "</p>")
            para = []

    for raw in src.splitlines():
        line = raw.rstrip()
        if not line.strip():
            flush(); continue
        if re.match(r"\s*#(set|let|show|import|metadata)\b", line) or "#pagebreak" in line:
            continue
        hm = re.match(r"\s*(=+)\s+(.+)$", line)
        if hm:
            flush()
            level = min(6, len(hm.group(1)) + 1)
            text = strip_markup(hm.group(2), variables)
            body.append(f"    <h{level}>{_html.escape(text)}</h{level}>")
        else:
            para.append(html_inline(strip_markup(line, variables)))
    flush()
    html = [
        "<!DOCTYPE html>",
        '<html lang="en">',
        "  <head>",
        '    <meta charset="utf-8">',
        '    <meta name="viewport" content="width=device-width, initial-scale=1">',
        "  </head>",
        "  <body>",
    ]
    html.extend(body)
    html.extend(["  </body>", "</html>", ""])
    return "\n".join(html).encode("utf-8")


# ---------------------------------------------------------------------------
# Compile/watch support


class CompileOptions(dict):
    def __getattr__(self, key: str) -> Any:
        return self.get(key)


def take_option_value(args: list[str], i: int, opt_display: str) -> tuple[str | None, int, int | None]:
    if i + 1 >= len(args):
        return None, i, missing_value(opt_display)
    val = args[i + 1]
    if val.startswith("-"):
        return None, i, unexpected_arg(val, "compile [OPTIONS] <INPUT> [OUTPUT]", allow_tip=True)
    return val, i + 1, None


def add_features(value: str, opts: CompileOptions) -> int | None:
    for feat in value.split(','):
        feat = feat.strip()
        if not feat:
            continue
        if feat not in FEATURES:
            return invalid_value(feat, "--features <FEATURES>", "html, a11y-extras")
        opts.setdefault("features", set()).add(feat)
    return None


def parse_pages_spec(spec: str, total: int | None = None) -> list[int] | None:
    selected: list[int] = []
    for part in spec.split(','):
        part = part.strip()
        if not part:
            return None
        if '-' in part:
            a, b = part.split('-', 1)
            if a and not a.isdigit():
                return None
            if b and not b.isdigit():
                return None
            start = int(a) if a else 1
            end = int(b) if b else (total if total is not None else start)
            if start <= 0 or end < start:
                return None
            if total is None:
                selected.extend(range(start, end + 1))
            else:
                selected.extend([p for p in range(start, min(end, total) + 1)])
        else:
            if not part.isdigit() or int(part) <= 0:
                return None
            p = int(part)
            if total is None or p <= total:
                selected.append(p)
    # Preserve order but remove duplicates.
    seen = set()
    result = []
    for p in selected:
        if p not in seen:
            result.append(p); seen.add(p)
    return result


def parse_compile_args(args: list[str], command: str = "compile") -> tuple[CompileOptions | None, int | None]:
    opts = CompileOptions(
        format=None, root=os.environ.get("TYPST_ROOT"), inputs={}, font_paths=[], ignore_system_fonts=False,
        ignore_embedded_fonts=False, package_path=None, package_cache_path=None, creation_timestamp=None,
        pages=None, pdf_standard=None, no_pdf_tags=False, ppi=144.0, deps=None, deps_format="json",
        jobs=None, features=set(), diagnostic_format="human", open=False, open_viewer=None, timings=None,
        no_serve=False, no_reload=False, port=None,
    )
    env_feats = os.environ.get("TYPST_FEATURES")
    if env_feats:
        rc = add_features(env_feats, opts)
        if rc is not None:
            return None, rc
    pos: list[str] = []
    after_dash = False
    i = 0
    while i < len(args):
        arg = args[i]
        if after_dash:
            pos.append(arg); i += 1; continue
        if arg == "--":
            after_dash = True; i += 1; continue
        if arg == "--help":
            out(help_text(command, True)); return None, 0
        if arg == "-h":
            out(help_text(command, False)); return None, 0
        # --name=value handling
        name, eq, val_eq = arg.partition("=") if arg.startswith("--") else (arg, "", "")
        def getval(display: str) -> tuple[str | None, int | None]:
            nonlocal i
            if eq:
                return val_eq, None
            val, ni, rc = take_option_value(args, i, display)
            if rc is not None:
                return None, rc
            i = ni
            return val, None
        if name in {"-f", "--format"}:
            val, rc = getval("--format <FORMAT>")
            if rc is not None: return None, rc
            if val not in {"pdf", "png", "svg", "html"}:
                return None, invalid_value(str(val), "--format <FORMAT>", "pdf, png, svg, html")
            opts.format = val
        elif name == "--root":
            val, rc = getval("--root <DIR>");
            if rc is not None: return None, rc
            opts.root = val
        elif name == "--input":
            val, rc = getval("--input <key=value>")
            if rc is not None: return None, rc
            if "=" not in str(val):
                return None, invalid_value(str(val), "--input <key=value>", reason="input must be a key and a value separated by an equal sign")
            k, v = str(val).split("=", 1); opts.inputs[k] = v
        elif name == "--font-path":
            val, rc = getval("--font-path <DIR>");
            if rc is not None: return None, rc
            opts.font_paths.extend(str(val).split(os.pathsep))
        elif name == "--ignore-system-fonts":
            opts.ignore_system_fonts = True
        elif name == "--ignore-embedded-fonts":
            opts.ignore_embedded_fonts = True
        elif name == "--package-path":
            val, rc = getval("--package-path <DIR>");
            if rc is not None: return None, rc
            opts.package_path = val
        elif name == "--package-cache-path":
            val, rc = getval("--package-cache-path <DIR>");
            if rc is not None: return None, rc
            opts.package_cache_path = val
        elif name == "--creation-timestamp":
            val, rc = getval("--creation-timestamp <UNIX_TIMESTAMP>")
            if rc is not None: return None, rc
            if not re.fullmatch(r"\d+", str(val)):
                return None, invalid_value(str(val), "--creation-timestamp <UNIX_TIMESTAMP>", reason="timestamp must be decimal integer (invalid digit found in string)")
            opts.creation_timestamp = int(str(val))
        elif name == "--pages":
            val, rc = getval("--pages <PAGES>")
            if rc is not None: return None, rc
            if parse_pages_spec(str(val), None) is None:
                return None, invalid_value(str(val), "--pages <PAGES>", reason="not a valid page number")
            opts.pages = str(val)
        elif name == "--pdf-standard":
            val, rc = getval("--pdf-standard <PDF_STANDARD>")
            if rc is not None: return None, rc
            for part in str(val).split(','):
                if part not in PDF_STANDARDS:
                    return None, invalid_value(part, "--pdf-standard <PDF_STANDARD>", "1.4, 1.5, 1.6, 1.7, 2.0, a-1b, a-1a, a-2b, a-2u, a-2a, a-3b, a-3u, a-3a, a-4, a-4f, a-4e, ua-1")
            opts.pdf_standard = str(val)
        elif name == "--no-pdf-tags":
            opts.no_pdf_tags = True
        elif name == "--ppi":
            val, rc = getval("--ppi <PPI>")
            if rc is not None: return None, rc
            try:
                opts.ppi = float(str(val))
            except ValueError:
                return None, invalid_value(str(val), "--ppi <PPI>", reason="invalid float literal")
        elif name == "--deps":
            val, rc = getval("--deps <PATH>")
            if rc is not None: return None, rc
            opts.deps = str(val)
        elif name == "--deps-format":
            val, rc = getval("--deps-format <DEPS_FORMAT>")
            if rc is not None: return None, rc
            if val not in {"json", "zero", "make"}:
                return None, invalid_value(str(val), "--deps-format <DEPS_FORMAT>", "json, zero, make")
            opts.deps_format = str(val)
        elif name in {"-j", "--jobs"}:
            val, rc = getval("--jobs <JOBS>")
            if rc is not None: return None, rc
            if not re.fullmatch(r"\d+", str(val)):
                return None, invalid_value(str(val), "--jobs <JOBS>", reason="invalid digit found in string")
            opts.jobs = int(str(val))
        elif name == "--features":
            val, rc = getval("--features <FEATURES>")
            if rc is not None: return None, rc
            rc2 = add_features(str(val), opts)
            if rc2 is not None: return None, rc2
        elif name == "--diagnostic-format":
            val, rc = getval("--diagnostic-format <DIAGNOSTIC_FORMAT>")
            if rc is not None: return None, rc
            if val not in {"human", "short"}:
                return None, invalid_value(str(val), "--diagnostic-format <DIAGNOSTIC_FORMAT>", "human, short")
            opts.diagnostic_format = str(val)
        elif name == "--open":
            opts.open = True
            if eq:
                opts.open_viewer = val_eq
            elif i + 1 < len(args) and not args[i + 1].startswith("-"):
                opts.open_viewer = args[i + 1]; i += 1
        elif name == "--timings":
            if eq:
                opts.timings = val_eq
            elif i + 1 < len(args) and not args[i + 1].startswith("-"):
                opts.timings = args[i + 1]; i += 1
            else:
                opts.timings = None
        elif command == "watch" and name in {"--no-serve", "--no-reload"}:
            opts[name[2:].replace('-', '_')] = True
        elif command == "watch" and name == "--port":
            val, rc = getval("--port <PORT>")
            if rc is not None: return None, rc
            opts.port = val
        elif arg.startswith("-"):
            return None, unexpected_arg(arg, f"{command} [OPTIONS] <INPUT> [OUTPUT]", allow_tip=True)
        else:
            pos.append(arg)
        i += 1
    opts.positionals = pos
    return opts, None


def infer_output(input_path: str, fmt: str | None) -> str:
    ext = fmt or "pdf"
    p = Path(input_path)
    if p.suffix:
        return str(p.with_suffix("." + ext))
    return str(p) + "." + ext


def infer_format(output_path: str, fmt: str | None) -> tuple[str | None, int | None]:
    if fmt:
        return fmt, None
    if output_path == "-":
        return "pdf", None
    ext = Path(output_path).suffix.lower().lstrip('.')
    if ext in {"pdf", "png", "svg", "html"}:
        return ext, None
    err(f"error: could not infer output format for path {output_path}.\nconsider providing the format manually with `--format/-f`\n")
    return None, 1


def format_source_error(path: str, line_no: int, col: int, message: str, line: str, diagnostic_format: str) -> str:
    if diagnostic_format == "short":
        return f"{path}:{line_no}:{col}: error: {message}\n"
    caret = " " * max(col - 1, 0) + "^"
    return f"error: {message}\n  ┌─ {path}:{line_no}:{col}\n  │\n{line_no} │ {line}\n  │ {caret}\n\n"


def analyze_source(src: str, input_path: str, base_dir: str | None, diagnostic_format: str) -> str | None:
    lines = src.splitlines()
    base = Path(base_dir or os.getcwd())
    for idx, line in enumerate(lines, 1):
        m = re.search(r"#(include|import)\s+\"([^\"]+)\"", line)
        if m:
            p = base / m.group(2)
            if not p.exists():
                searched = str(p.resolve())
                col = m.start(2)
                msg = f"file not found (searched at {searched})"
                return format_source_error(input_path, idx, max(col, 1), msg, line, diagnostic_format)
        if re.match(r"\s*#let\s+[A-Za-z_][\w-]*\s*=\s*$", line):
            col = max(1, len(line.rstrip()))
            return format_source_error(input_path, idx, col, "expected expression", line, diagnostic_format)
    return None


def os_error_message(e: OSError) -> str:
    if e.errno:
        return f"{e.strerror} (os error {e.errno})"
    return str(e)


def write_bytes(path: str, data: bytes, fmt: str) -> int | None:
    if path == "-":
        sys.stdout.buffer.write(data)
        return None
    try:
        Path(path).write_bytes(data)
        return None
    except OSError as e:
        err(f"error: failed to write {fmt.upper()} file ({os_error_message(e)})\n")
        return 1


def apply_page_template(path: str, page_no: int, total: int) -> str:
    width = len(str(total))
    return path.replace("{0p}", str(page_no).zfill(width)).replace("{p}", str(page_no)).replace("{t}", str(total))


def collect_deps(src: str, input_path: str, base_dir: str | None) -> list[str]:
    deps: set[str] = set()
    if input_path != "-":
        deps.add(input_path)
    base = Path(base_dir or os.getcwd())
    for m in re.finditer(r"#include\s+\"([^\"]+)\"", src):
        p = base / m.group(1)
        if p.exists():
            try:
                deps.add(os.path.relpath(str(p.resolve()), os.getcwd()))
            except Exception:
                deps.add(str(p))
    return sorted(deps)


def format_deps(inputs: list[str], outputs: list[str], deps_format: str) -> bytes:
    if deps_format == "zero":
        return ("\0".join(inputs) + ("\0" if inputs else "")).encode()
    if deps_format == "make":
        return (" ".join(outputs) + ": " + " ".join(inputs) + "\n").encode()
    return json.dumps({"inputs": inputs, "outputs": outputs}, separators=(",", ":")).encode()


def compile_command(args: list[str], command: str = "compile", watch_mode: bool = False) -> int:
    opts, rc = parse_compile_args(args, "watch" if command == "watch" else "compile")
    if rc is not None:
        return rc
    assert opts is not None
    pos = opts.positionals
    if not pos:
        return required_args(["<INPUT>"], f"{command} <INPUT> [OUTPUT]")
    if len(pos) == 1 and pos[0] == "-":
        return required_args(["<OUTPUT>"], f"{command} <INPUT> <OUTPUT>")
    if len(pos) > 2:
        return unexpected_arg(pos[2], f"{command} [OPTIONS] <INPUT> [OUTPUT]", allow_tip=False)
    input_path = pos[0]
    output_path = pos[1] if len(pos) > 1 else infer_output(input_path, opts.format)
    fmt, erc = infer_format(output_path, opts.format)
    if erc is not None:
        return erc
    assert fmt is not None
    if output_path == "-" and opts.deps == "-":
        err("error: cannot write both output and dependencies to stdout\n")
        return 1
    if opts.root and not Path(str(opts.root)).exists():
        err(f"error: root directory not found (searched at {opts.root})\n")
        return 1
    if fmt == "html" and "html" not in opts.features:
        err(HTML_FEATURE_ERROR)
        return 1

    base_dir: str | None = None
    if input_path == "-":
        src = sys.stdin.read()
        base_dir = os.getcwd()
    else:
        p = Path(input_path)
        if not p.exists():
            err(f"error: input file not found (searched at {input_path})\n")
            return 1
        try:
            src = p.read_text()
        except UnicodeDecodeError:
            src = p.read_bytes().decode("utf-8", "replace")
        base_dir = str(p.parent if str(p.parent) else Path.cwd())
    diagnostic = analyze_source(src, input_path, base_dir, opts.diagnostic_format)
    if diagnostic:
        err(diagnostic)
        return 1

    pages_text = plain_pages(src, base_dir)
    total_pages = len(pages_text)
    selected_nums = parse_pages_spec(opts.pages, total_pages) if opts.pages else list(range(1, total_pages + 1))
    selected_pages = [pages_text[n - 1] for n in selected_nums]
    outputs: list[str] = []

    if fmt == "pdf":
        data = make_pdf(selected_pages or [[""]], title=Path(input_path).stem if input_path != "-" else None)
        rcw = write_bytes(output_path, data, fmt)
        if rcw is not None: return rcw
        if output_path != "-": outputs.append(output_path)
    elif fmt == "html":
        err(HTML_WARNING)
        data = make_html(src, base_dir)
        rcw = write_bytes(output_path, data, fmt)
        if rcw is not None: return rcw
        if output_path != "-": outputs.append(output_path)
    elif fmt in {"svg", "png"}:
        if len(selected_pages) > 1:
            if output_path == "-":
                err(f"error: cannot export multiple images to stdout\n")
                return 1
            if "{p}" not in output_path and "{0p}" not in output_path:
                err("error: cannot export multiple images without a page number template ({p}, {0p}) in the output path\n")
                return 1
        for n, lines in zip(selected_nums, selected_pages):
            dest = output_path if len(selected_pages) <= 1 else apply_page_template(output_path, n, total_pages)
            if "{p}" in dest or "{0p}" in dest or "{t}" in dest:
                dest = apply_page_template(dest, n, total_pages)
            data = make_svg(lines) if fmt == "svg" else make_png(float(opts.ppi))
            rcw = write_bytes(dest, data, fmt)
            if rcw is not None: return rcw
            if dest != "-": outputs.append(dest)
    else:
        return 1

    if opts.deps:
        inputs = collect_deps(src, input_path, base_dir)
        dep_data = format_deps(inputs, outputs or ([output_path] if output_path != "-" else []), opts.deps_format)
        if opts.deps == "-":
            sys.stdout.buffer.write(dep_data)
        else:
            try:
                Path(opts.deps).write_bytes(dep_data)
            except OSError as e:
                err(f"error: failed to write dependencies ({os_error_message(e)})\n")
                return 1

    if opts.timings and opts.timings != "-":
        timings = [{"name": "compile once", "cat": "typst", "ph": "B", "ts": 0.0, "pid": 1, "tid": 1, "args": None}]
        try:
            Path(opts.timings).write_text(json.dumps(timings, separators=(",", ":")))
        except OSError:
            pass

    if opts.open and opts.open_viewer is None and output_path != "-":
        err("error: failed to open file with any of these resource openers: xdg-open, gio, gnome-open, kde-open (No such file or directory (os error 2))\n")
        return 1
    return 0


def watch_command(args: list[str]) -> int:
    # Parse once to find input/output for status messages, then compile.
    opts, rc = parse_compile_args(args, "watch")
    if rc is not None:
        return rc
    assert opts is not None
    pos = opts.positionals
    if not pos:
        return required_args(["<INPUT>"], "watch <INPUT> [OUTPUT]")
    input_path = pos[0]
    output_path = pos[1] if len(pos) > 1 else infer_output(input_path, opts.format)
    def status(prefix: str) -> None:
        err(f"watching {input_path}\nwriting to {output_path}\n\n")
        err(f"[{time.strftime('%H:%M:%S')}] {prefix}\n\n")
    status("compiling ...")
    rc2 = compile_command(args, "watch")
    err(f"watching {input_path}\nwriting to {output_path}\n\n")
    if rc2 == 0:
        err(f"[{time.strftime('%H:%M:%S')}] compiled successfully in 1.00 ms\n\n")
    else:
        err(f"[{time.strftime('%H:%M:%S')}] compiled with errors\n\n")
    try:
        while True:
            time.sleep(3600)
    except KeyboardInterrupt:
        return 130


